<script setup>defineProps({title:{default:'Tu avance'},value:[String,Number],unit:String,summary:String,breakdown:{default:()=>[]}})</script>
<template><section class="progress"><p class="progress__title">{{title}}</p><div class="progress__value"><strong>{{value}}</strong><span v-if="unit">{{unit}}</span></div><p v-if="summary" class="progress__summary">{{summary}}</p><ul v-if="breakdown.length"><li v-for="item in breakdown" :key="item.label" :style="{'--c':item.color}"><i aria-hidden="true"/><span>{{item.label}}</span><strong>{{item.value}}</strong></li></ul></section></template>
<style scoped>.progress{display:flex;padding:var(--pad-card);flex-direction:column;gap:12px;border:1px solid var(--border-subtle);border-radius:var(--radius-lg);background:var(--surface-primary)}.progress__title,.progress__summary{margin:0}.progress__title{color:var(--text-muted);font:600 12px/1 var(--font-core);letter-spacing:.06em;text-transform:uppercase}.progress__value{display:flex;align-items:baseline;gap:8px}.progress__value strong{color:var(--text-primary);font:500 40px/1 var(--font-numeric);font-variant-numeric:tabular-nums;letter-spacing:-.02em}.progress__value span{color:var(--text-secondary);font:400 14px/1 var(--font-core)}.progress__summary{color:var(--text-secondary);font:400 14px/1.5 var(--font-core);text-wrap:pretty}.progress ul{display:flex;margin:0;padding:0;flex-direction:column;gap:8px;list-style:none}.progress li{display:flex;align-items:center;gap:10px}.progress li i{display:block;width:10px;height:10px;flex:none;border-radius:3px;background:var(--c,var(--progress-complete))}.progress li span{flex:1;color:var(--text-secondary);font:400 14px/1 var(--font-core)}.progress li strong{color:var(--text-primary);font:600 14px/1 var(--font-numeric);font-variant-numeric:tabular-nums}</style>
